# Load the countries layer to identify Central Asian countries
countries = load("countries")

# Filter for Central Asian countries using the correct field name 'NAME_EN'
central_asian_countries = filter_features(countries, '"NAME_EN" IN (\'Kyrgyzstan\', \'Tajikistan\', \'Turkmenistan\', \'Uzbekistan\', \'Kazakhstan\')')

# Load energy security metrics tables
gdp_per_capita = read_table("gdp_per_capita_usd")
electric_power_consumption = read_table("electric_power_consumption_kwh_per_capita")
co2_emissions = read_table("co2_emissions_per_capita")
ghg_emissions = read_table("ghg_emissions_per_capita")

# Print the metrics for each country
print("Energy Security Metrics for Central Asian Countries:")
print("=" * 60)

# Get country names from the filtered layer
country_names = [row["NAME_EN"] for row in rows(central_asian_countries)]

# Print GDP per capita
print("\nGDP per Capita (current US$):")
for country in country_names:
    gdp_row = gdp_per_capita[gdp_per_capita["Country Name"] == country]
    if not gdp_row.empty:
        gdp_value = gdp_row.iloc[0]["2023"]
        if gdp_value is not None and gdp_value != 'nan':
            print(f"  {country}: ${gdp_value:.2f}")
        else:
            print(f"  {country}: N/A")
    else:
        print(f"  {country}: N/A")

# Print electric power consumption
print("\nElectric Power Consumption (kWh per capita):")
for country in country_names:
    consumption_row = electric_power_consumption[electric_power_consumption["Country Name"] == country]
    if not consumption_row.empty:
        consumption_value = consumption_row.iloc[0]["2023"]
        if consumption_value is not None and consumption_value != 'nan':
            print(f"  {country}: {consumption_value:.2f} kWh")
        else:
            print(f"  {country}: N/A")
    else:
        print(f"  {country}: N/A")

# Print CO2 emissions per capita
print("\nCO2 Emissions per Capita (tons):")
for country in country_names:
    co2_row = co2_emissions[co2_emissions["Country name"] == country]
    if not co2_row.empty:
        co2_value = co2_row.iloc[0]["2023"]
        if co2_value is not None and co2_value != 'nan':
            print(f"  {country}: {co2_value:.2f} tons")
        else:
            print(f"  {country}: N/A")
    else:
        print(f"  {country}: N/A")

# Print GHG emissions per capita
print("\nGreenhouse Gas Emissions per Capita (tons CO2-equivalent):")
for country in country_names:
    ghg_row = ghg_emissions[ghg_emissions["Country Name"] == country]
    if not ghg_row.empty:
        ghg_value = ghg_row.iloc[0]["2023"]
        if ghg_value is not None and ghg_value != 'nan':
            print(f"  {country}: {ghg_value:.2f} tons")
        else:
            print(f"  {country}: N/A")
    else:
        print(f"  {country}: N/A")

# Save the filtered countries layer for visualization
save(central_asian_countries, "central_asian_countries")
